-- GenDB engine variant Q09-commuted_comparisons: template q09.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  nation,
  o_year,
  SUM(amount) AS sum_profit
FROM (
  SELECT
    n_name AS nation,
    EXTRACT(YEAR FROM o_orderdate) AS o_year,
    l_extendedprice * (
      1 - l_discount
    ) - ps_supplycost * l_quantity AS amount
  FROM part, supplier, lineitem, partsupp, orders, nation
  WHERE
    l_suppkey = s_suppkey
    AND l_suppkey = ps_suppkey
    AND l_partkey = ps_partkey
    AND l_partkey = p_partkey
    AND l_orderkey = o_orderkey
    AND n_nationkey = s_nationkey
    AND p_name LIKE $1
) AS profit
GROUP BY
  nation,
  o_year
ORDER BY
  nation,
  o_year DESC
